import { createLogger } from '../utils/logger';

const log = createLogger('SupabaseAuthService');

export interface VerifiedUser {
  id: string;
  email?: string;
}

export class SupabaseAuthService {
  private readonly url: string;
  private readonly anonKey: string;

  constructor(opts?: { url?: string; anonKey?: string }) {
    const url = opts?.url ?? process.env.SUPABASE_URL;
    const anonKey = opts?.anonKey ?? process.env.SUPABASE_ANON_KEY;
    if (!url || !anonKey) {
      throw new Error(
        'SUPABASE_URL and SUPABASE_ANON_KEY must be set to verify auth tokens',
      );
    }
    this.url = url.replace(/\/+$/, '');
    this.anonKey = anonKey;
  }

  async verifyToken(token: string): Promise<VerifiedUser | null> {
    if (!token) return null;
    try {
      const res = await fetch(`${this.url}/auth/v1/user`, {
        headers: {
          apikey: this.anonKey,
          Authorization: `Bearer ${token}`,
        },
        signal: AbortSignal.timeout(10_000),
      });
      if (!res.ok) {
        log.debug(`Token verification failed (${res.status})`);
        return null;
      }
      const user = (await res.json()) as { id?: string; email?: string };
      if (!user?.id) return null;
      return { id: user.id, email: user.email };
    } catch (err) {
      log.warn('Error verifying token', err);
      return null;
    }
  }
}
